	// the binding stays on b regardless.
	markHealth(t, r, "svc", "a", 2, 1, true, "")
	if out := selectedWithSession(t, r, "svc", 2, "s"); out.InstanceID != "b" {
		t.Fatalf("binding should stay on b: %+v", out)
