1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"io"
8		"os"
9		"strings"
10		"testing"
11	)
12	
13	// runRegisterWith runs runRegister with the given stdin and captured stdout.
14	func runRegisterWith(t *testing.T, input string) (string, int) {
15		t.Helper()
16		oldStdin := os.Stdin
17		oldStdout := os.Stdout
18		defer func() {
19			os.Stdin = oldStdin
20			os.Stdout = oldStdout
21		}()
22		inR, inW, err := os.Pipe()
23		if err != nil {
24			t.Fatalf("pipe: %v", err)
25		}
26		os.Stdin = inR
27		go func() {
28			defer inW.Close()
29			_, _ = inW.WriteString(input)
30		}()
31		outR, outW, err := os.Pipe()
32		if err != nil {
33			t.Fatalf("pipe: %v", err)
34		}
35		os.Stdout = outW
36		code := runRegister()
37		outW.Close()
38		var buf bytes.Buffer
39		if _, err := buf.ReadFrom(outR); err != nil {
40			t.Fatalf("read stdout: %v", err)
41		}
42		return buf.String(), code
43	}
44	
45	func TestRegisterSuccess(t *testing.T) {
46		input := `{"requests":[
47			{"service":"b","expectedRevision":0,"instances":[{"id":"b2","address":"h2:2"},{"id":"b1","address":"h1:1"}]},
48			{"service":"b","expectedRevision":1,"instances":[{"id":"b1","address":"h1:1"},{"id":"b2","address":"h2:2"}]},
49			{"service":"a","expectedRevision":0,"instances":[]}
50		]}`
51		out, code := runRegisterWith(t, input)
52		if code != 0 {
53			t.Fatalf("exit code: %d, output: %s", code, out)
54		}
55		var got registerOutput
56		if err := json.Unmarshal([]byte(out), &got); err != nil {
57			t.Fatalf("output is not JSON: %v\n%s", err, out)
58		}
59		if len(got.Results) != 3 {
60			t.Fatalf("results: %+v", got.Results)
61		}
62		want := []registerResult{
63			{Service: "b", OK: true, Changed: true, Revision: 1},
64			{Service: "b", OK: true, Changed: false, Revision: 1},
65			{Service: "a", OK: true, Changed: true, Revision: 1},
66		}
67		for i := range want {
68			if got.Results[i] != want[i] {
69				t.Fatalf("result %d: got %+v want %+v", i, got.Results[i], want[i])
70			}
71		}
72		// Services sorted by name; instances sorted by id; empty list kept.
73		if len(got.Services) != 2 {
74			t.Fatalf("services: %+v", got.Services)
75		}
76		if got.Services[0].Service != "a" || got.Services[0].Revision != 1 || len(got.Services[0].Instances) != 0 {
77			t.Fatalf("service a: %+v", got.Services[0])
78		}
79		if got.Services[1].Service != "b" || got.Services[1].Revision != 1 {
80			t.Fatalf("service b: %+v", got.Services[1])
81		}
82		insts := got.Services[1].Instances
83		if len(insts) != 2 || insts[0].ID != "b1" || insts[0].Address != "h1:1" || insts[1].ID != "b2" {
84			t.Fatalf("service b instances: %+v", insts)
85		}
86	}
87	
88	func TestRegisterFailuresDoNotAbort(t *testing.T) {
89		input := `{"requests":[
90			{"service":"a","expectedRevision":0,"instances":[{"id":"x","address":"h:1"}]},
91			{"service":"a","expectedRevision":5,"instances":[{"id":"y","address":"h:2"}]},
92			{"service":"a","expectedRevision":1,"instances":[{"id":"y","address":"h:2"}]},
93			{"service":"a","expectedRevision":2,"instances":[{"id":"","address":"h:1"}]},
94			{"service":"a","expectedRevision":2,"instances":[{"id":"z","address":"nope"}]},
95			{"service":"b","expectedRevision":1,"instances":[]}
96		]}`
97		out, code := runRegisterWith(t, input)
98		if code != 1 {
99			t.Fatalf("exit code: %d", code)
100		}
101		var got registerOutput
102		if err := json.Unmarshal([]byte(out), &got); err != nil {
103			t.Fatalf("output is not JSON: %v\n%s", err, out)
104		}
105		if len(got.Results) != 6 {
106			t.Fatalf("results: %+v", got.Results)
107		}
108		// 0: create
109		if r := got.Results[0]; !r.OK || !r.Changed || r.Revision != 1 {
110			t.Fatalf("result 0: %+v", r)
111		}
112		// 1: conflict, expected 5 actual 1
113		if r := got.Results[1]; r.OK || r.Error != "conflict" || r.ExpectedRevision != 5 || r.ActualRevision != 1 || r.Revision != 1 {
114			t.Fatalf("result 1: %+v", r)
115		}
116		// 2: update to rev 2
117		if r := got.Results[2]; !r.OK || !r.Changed || r.Revision != 2 {
118			t.Fatalf("result 2: %+v", r)
119		}
120		// 3: invalid content with a matching revision: still invalid, list untouched
121		if r := got.Results[3]; r.OK || r.Error != "invalid" || r.Revision != 2 {
122			t.Fatalf("result 3: %+v", r)
123		}
124		// 4: invalid address
125		if r := got.Results[4]; r.OK || r.Error != "invalid" || r.Revision != 2 {
126			t.Fatalf("result 4: %+v", r)
127		}
128		// 5: conflict on a brand-new service
129		if r := got.Results[5]; r.OK || r.Error != "conflict" || r.ExpectedRevision != 1 || r.ActualRevision != 0 || r.Revision != 0 {
130			t.Fatalf("result 5: %+v", r)
131		}
