1734		if code != 1 {
1735			t.Fatalf("batch contains failures, exit code: %d, output: %s", code, out)
1736		}
1737		var got registerOutput
1738		if err := json.Unmarshal([]byte(out), &got); err != nil {
1739			t.Fatalf("output is not JSON: %v\n%s", err, out)
1740		}
1741		// One result per request, in input order; failed items keep their slots.
1742		if len(got.Results) != 16 {
