1744		}
1745		// 4-5: bind s -> a, then a plain select rotates to b; the cursor rests on b.
1746		if r := got.Results[4]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 11 {
1747			t.Fatalf("session bind: %+v", r)
1748		}
1749		if r := got.Results[5]; !r.OK || r.InstanceID != "b" || r.Sequence != 12 {
1750			t.Fatalf("plain select: %+v", r)
1751		}
1752		// 6: the replacement resets a to unknown at its new address, revision 2.
1753		if r := got.Results[6]; !r.OK || !r.Changed || r.Revision != 2 {
