2200	// TestSelectSessionKeyClearListThenReadd is the batch-level regression guard
2201	// for the session-persistence condition "clear the service's instance list,
2202	// then re-add instances". Clearing removes the instances together with their
2203	// health records but keeps the service, its rotation position and the session
2204	// bindings; whether the old session can still reach its target is judged from
2205	// the instance state at the next selection. The batch walks:
2206	//
2207	//   - a, b, c registered at revision 1 and observed healthy at sequences above
2208	//     1; the key first selects a (binding s -> a), then a keyless selection
2209	//     advances the rotation to b, the last real rotation;
2210	//   - an empty-list replacement at revision 1 succeeds, reports changed and
2211	//     bumps the revision to 2 without deleting the service;
2212	//   - the session's request at revision 2 fails with no_healthy — never
2213	//     not_found — naming the current revision and a non-empty reason and
2214	//     carrying no pre-clear instance id, address or health sequence; the
2215	//     failure rewrites the binding and moves the cursor neither;
2216	//   - re-adding the original ids at revision 2 bumps the revision to 3: the
2217	//     bound instance a comes back at a NEW address, while b and c keep their
2218	//     old addresses, yet all three start at unknown/0/no reason; with no fresh
2219	//     observation accepted the session still fails no_healthy at revision 3;
2220	//   - fresh observations at revision 3 use positive sequence 1 even though it
2221	//     is below the pre-clear sequences; the session then reuses its surviving
2222	//     binding and returns a at the new address h9:9 with sequence 1;
2223	//   - a keyless selection continues from the rotation position preserved
2224	//     through the clear (just after b) and lands on c, rather than being
2225	//     pulled back to the bound instance a by the session reuse or by the
2226	//     failed requests; the next one wraps to a.
2227	//
2228	// The batch contains selection failures, so the process exits 1: the failed
2229	// items keep their own result slots while the later registration, health
2230	// reports and selections continue to take effect, and no selection changes
2231	// the registration revision or an accepted health record.
2232	func TestSelectSessionKeyClearListThenReadd(t *testing.T) {
2233		input := `{"requests":[
2234			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"}]},
2235			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":11,"healthy":true},
2236			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":12,"healthy":true},
2237			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":13,"healthy":true},
2238			{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"s"},
2239			{"type":"select","service":"svc","expectedRevision":1},
2240			{"type":"register","service":"svc","expectedRevision":1,"instances":[]},
2241			{"type":"select","service":"svc","expectedRevision":2,"sessionKey":"s"},
2242			{"type":"register","service":"svc","expectedRevision":2,"instances":[{"id":"a","address":"h9:9"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"}]},
2243			{"type":"select","service":"svc","expectedRevision":3,"sessionKey":"s"},
2244			{"type":"health","service":"svc","instanceId":"a","expectedRevision":3,"sequence":1,"healthy":true},
2245			{"type":"health","service":"svc","instanceId":"c","expectedRevision":3,"sequence":1,"healthy":true},
2246			{"type":"select","service":"svc","expectedRevision":3,"sessionKey":"s"},
2247			{"type":"select","service":"svc","expectedRevision":3},
2248			{"type":"select","service":"svc","expectedRevision":3},
2249			{"type":"select","service":"svc","expectedRevision":3,"sessionKey":"s"}
2250		]}`
2251		out, code := runRegisterWith(t, input)
2252		if code != 1 {
2253			t.Fatalf("batch contains selection failures, exit code: %d, output: %s", code, out)
2254		}
2255		var got registerOutput
2256		if err := json.Unmarshal([]byte(out), &got); err != nil {
2257			t.Fatalf("output is not JSON: %v\n%s", err, out)
2258		}
2259		// One result per request, in input order; the failed selections keep their
2260		// own slots and later items still land in theirs.
2261		if len(got.Results) != 16 {
2262			t.Fatalf("results: %+v", got.Results)
2263		}
2264		// 0: registration accepted at revision 1.
2265		if r := got.Results[0]; !r.OK || !r.Changed || r.Revision != 1 {
2266			t.Fatalf("result 0: %+v", r)
2267		}
2268		// 1-3: observations accepted without bumping the registration revision.
2269		if r := got.Results[1]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 11 {
2270			t.Fatalf("result 1: %+v", r)
2271		}
2272		if r := got.Results[2]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 12 {
2273			t.Fatalf("result 2: %+v", r)
2274		}
2275		if r := got.Results[3]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 13 {
2276			t.Fatalf("result 3: %+v", r)
2277		}
2278		// 4: the key's first success rotates to the smallest id and binds s -> a,
2279		// carrying a's pre-clear address and accepted sequence.
2280		if r := got.Results[4]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 11 || r.Revision != 1 {
2281			t.Fatalf("result 4 session bind: %+v", r)
2282		}
2283		// 5: a keyless selection advances the rotation to b, the last real
2284		// rotation before the clear.
2285		if r := got.Results[5]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 12 || r.Revision != 1 {
2286			t.Fatalf("result 5 keyless rotation: %+v", r)
2287		}
2288		// 6: clearing the instance list succeeds, reports the change and bumps the
2289		// revision to 2; the service itself stays.
2290		if r := got.Results[6]; !r.OK || !r.Changed || r.Revision != 2 {
2291			t.Fatalf("result 6 clear: %+v", r)
2292		}
2293		// 7: the service survived at revision 2, so the session request is
2294		// no_healthy — never not_found — with the current revision and a non-empty
2295		// reason, fabricating no pre-clear instance id, address or sequence. The
2296		// failure rewrites the s -> a binding and moves the cursor neither.
2297		if r := got.Results[7]; r.OK || r.Error != "no_healthy" || r.Reason == "" ||
2298			r.Revision != 2 || r.InstanceID != "" || r.Address != "" || r.Sequence != 0 {
2299			t.Fatalf("result 7 no_healthy on the cleared service: %+v", r)
2300		}
2301		// 8: re-adding the original ids succeeds at revision 2 and bumps to 3; a
2302		// uses a new address while b and c merely keep their old addresses.
2303		if r := got.Results[8]; !r.OK || !r.Changed || r.Revision != 3 {
2304			t.Fatalf("result 8 re-add: %+v", r)
2305		}
2306		// 9: identical ids and addresses restore no old health: every instance is
2307		// unknown again, so before any fresh observation the same session still
2308		// fails no_healthy at the current revision 3 with no fabricated target.
2309		if r := got.Results[9]; r.OK || r.Error != "no_healthy" || r.Reason == "" ||
2310			r.Revision != 3 || r.InstanceID != "" || r.Address != "" || r.Sequence != 0 {
2311			t.Fatalf("result 9 no_healthy before fresh observations: %+v", r)
2312		}
2313		// 10-11: fresh observations at the post-readd revision are accepted with
2314		// positive sequence 1, which is below the pre-clear sequences; health
2315		// reports never bump the registration revision, which stays 3.
2316		if r := got.Results[10]; !r.OK || !r.Changed || r.Revision != 3 || r.Sequence != 1 {
2317			t.Fatalf("result 10: %+v", r)
2318		}
2319		if r := got.Results[11]; !r.OK || !r.Changed || r.Revision != 3 || r.Sequence != 1 {
2320			t.Fatalf("result 11: %+v", r)
2321		}
2322		// 12: the binding survived the clear and the failed requests, so the
2323		// session reuses a — returning its CURRENT post-readd address h9:9 and the
2324		// new sequence 1, never h1:1/11 — and leaves the rotation on b.
2325		if r := got.Results[12]; !r.OK || r.InstanceID != "a" || r.Address != "h9:9" || r.Sequence != 1 || r.Revision != 3 {
2326			t.Fatalf("result 12 session reuse after recovery: %+v", r)
2327		}
2328		// 13: the session reuse and the two failed selections moved no cursor, so
2329		// the keyless rotation continues just after the pre-clear position b and
2330		// lands on c (b is unknown), not on the bound a.
2331		if r := got.Results[13]; !r.OK || r.InstanceID != "c" || r.Address != "h3:3" || r.Sequence != 1 || r.Revision != 3 {
2332			t.Fatalf("result 13 keyless selection should resume after b at c: %+v", r)
2333		}
2334		// 14: only now does the rotation wrap past c back to a, with its current
2335		// address and sequence.
2336		if r := got.Results[14]; !r.OK || r.InstanceID != "a" || r.Address != "h9:9" || r.Sequence != 1 || r.Revision != 3 {
2337			t.Fatalf("result 14 keyless selection should wrap to a: %+v", r)
2338		}
2339		// 15: the plain rotation rewrote no binding; the session still answers a
2340		// with the post-readd record.
2341		if r := got.Results[15]; !r.OK || r.InstanceID != "a" || r.Address != "h9:9" || r.Sequence != 1 || r.Revision != 3 {
2342			t.Fatalf("result 15 session binding after plain rotation: %+v", r)
2343		}
2344	
2345		// The final snapshot shows the service at revision 3 (selections changed
2346		// no revision) with the instances sorted by id: a healthy at its new
2347		// address from the fresh observation, c healthy from its own fresh
2348		// observation, and b — which only kept its old address — still unknown at
2349		// sequence 0 with no reason, proving identical ids/addresses restored no
2350		// pre-clear health record.
2351		if len(got.Services) != 1 {
2352			t.Fatalf("services: %+v", got.Services)
2353		}
2354		svc := got.Services[0]
2355		if svc.Service != "svc" || svc.Revision != 3 {
2356			t.Fatalf("service view: %+v", svc)
2357		}
2358		if len(svc.Instances) != 3 {
2359			t.Fatalf("instances: %+v", svc.Instances)
2360		}
2361		wantInsts := []registerInstance{
2362			{ID: "a", Address: "h9:9", Health: "healthy", Sequence: 1},
2363			{ID: "b", Address: "h2:2", Health: "unknown", Sequence: 0},
2364			{ID: "c", Address: "h3:3", Health: "healthy", Sequence: 1},
2365		}
2366		for i, want := range wantInsts {
2367			if svc.Instances[i] != want {
2368				t.Fatalf("instance %d: got %+v want %+v", i, svc.Instances[i], want)
2369			}
2370		}
