2373	// failingWriter fails every Write with errWriteBroken, optionally accepting the
2374	// first failAfter bytes to emulate an output destination that becomes unwritable
2375	// partway through the result document.
2376	type failingWriter struct {
2377		buf       bytes.Buffer
2378		failAfter int
2379	}
2380	
2381	var errWriteBroken = errors.New("disk on fire")
2382	
2383	func (w *failingWriter) Write(p []byte) (int, error) {
2384		if w.failAfter <= 0 {
2385			return 0, errWriteBroken
2386		}
2387		take := min(w.failAfter, len(p))
2388		n, _ := w.buf.Write(p[:take])
2389		w.failAfter -= take
2390		if take < len(p) {
2391			// A writer that accepts only part of p must return n < len(p) and the
2392			// failure without panic; json.Encoder stops at that point.
2393			return n, errWriteBroken
2394		}
2395		return n, nil
2396	}
