2398	// runRegisterIOWith runs runRegisterIO with normal stdin plus the given stdout
2399	// writer, capturing stderr. It returns the exit code, whatever reached stdout
2400	// and the stderr text.
2401	func runRegisterIOWith(t *testing.T, input string, out io.Writer) (int, string, string) {
2402		t.Helper()
2403		var stderr bytes.Buffer
2404		code := runRegisterIO(strings.NewReader(input), out, &stderr)
2405		return code, string(writerBytes(out)), stderr.String()
2406	}
2407	
2408	func writerBytes(w io.Writer) []byte {
2409		if fw, ok := w.(*failingWriter); ok {
2410			return fw.buf.Bytes()
2411		}
2412		return nil
2413	}
